def luhn_valid(number: str) -> bool:
    """Return whether the string passes the Luhn checksum. Spaces are ignored. Any other non-digit character makes it invalid, and so do strings with fewer than 2 digits."""
    digits = []
    for ch in number:
        if ch == " ":
            continue
        if not ch.isdigit():
            return False
        digits.append(int(ch))

    if len(digits) < 2:
        return False

    total = 0
    # Starting from the rightmost digit (the check digit), double every second digit.
    for i, d in enumerate(reversed(digits)):
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d

    return total % 10 == 0
EOF
