cd /repo && cat > solution.py << 'EOF'
def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    """Merge intervals [start, end]. Intervals that overlap or touch (one ends where the next starts) are merged into one. Return the merged intervals sorted by start."""
    if not intervals:
        return []

    # Sort intervals by their start value.
    sorted_intervals = sorted(intervals, key=lambda interval: interval[0])

    merged = [list(sorted_intervals[0])]
    for start, end in sorted_intervals[1:]:
        last = merged[-1]
        # Overlap or touch: merge into the current interval.
        if start <= last[1]:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])

    return merged
EOF
